#include <vector>
#include <string>
#include <algorithm>

class Solution {
public:
    int numberOfBeams(std::vector<std::string>& bank) {
        int totalBeams = 0;
        int prevDevices = 0;

        for (const auto& row : bank) {
            int count = std::count(row.begin(), row.end(), '1');
            if (count > 0) {
                totalBeams += prevDevices * count;
                prevDevices = count;
            }
        }
        return totalBeams;
    }
};

class Solution {
    public int numberOfBeams(String[] bank) {
        int totalBeams = 0;
        int prevDevices = 0;

        for (String row : bank) {
            int count = 0;
            for (int i = 0; i < row.length(); i++) {
                if (row.charAt(i) == '1') count++;
            }
            if (count > 0) {
                totalBeams += prevDevices * count;
                prevDevices = count;
            }
        }
        return totalBeams;
    }
}

