var numberOfBeams = function(bank) {
    let totalBeams = 0;
    let prevDevices = 0;

    for (const row of bank) {
        let count = 0;
        for (let i = 0; i < row.length; i++) {
            if (row[i] === '1') count++;
        }
        if (count > 0) {
            totalBeams += prevDevices * count;
            prevDevices = count;
        }
    }
    return totalBeams;
};
